import { test, expect } from '@playwright/test';

test.describe('Notification Click Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should navigate to related content when clicking a notification', async ({ page }) => {
    // Verify notification list is visible
    const notificationList = page.getByRole('region', { name: /notifications/i });
    await expect(notificationList).toBeVisible();

    // Verify notification items are present
    const notificationItems = page.getByRole('listitem');
    const count = await notificationItems.count();
    expect(count).toBeGreaterThan(0);

    // Get the first notification item
    const firstNotification = page.getByRole('listitem').first();
    await expect(firstNotification).toBeVisible();

    // Verify notification content is displayed
    const notificationTitle = page.getByText(/new message/i);
    await expect(notificationTitle).toBeVisible();

    // Verify notification action button exists
    const notificationAction = page.getByRole('button', { name: /view/i });
    await expect(notificationAction).toBeVisible();

    // Click the notification to navigate
    await notificationAction.click();

    // Wait for navigation to complete
    await page.waitForURL(/.*\/messages.*$/);

    // Verify navigation to messages page
    await expect(page).toHaveURL(/.*\/messages.*$/);

    // Verify messages page title is displayed
    const messagesPageTitle = page.getByRole('heading', { name: /messages/i });
    await expect(messagesPageTitle).toBeVisible();

    // Verify notification is marked as read
    const notificationStatus = page.getByText(/read/i);
    await expect(notificationStatus).toBeVisible();
  });

  test('should handle notification click when no related content exists', async ({ page }) => {
    // Intercept the API call for a notification with no content
    await page.route('**/api/notifications/123', route => {
      route.abort('failed');
    });

    // Click the notification with no content
    const notificationItem = page.getByRole('listitem', { name: /no content/i });
    await expect(notificationItem).toBeVisible();
    await notificationItem.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/no content available/i);
    await expect(errorMessage).toBeVisible();

    // Verify user remains on notifications page
    await expect(page).toHaveURL(/.*\/notifications/);

    // Verify notification is still visible
    await expect(notificationItem).toBeVisible();

    // Verify error state is displayed
    const errorState = page.getByRole('status');
    await expect(errorState).toContainText('error');
  });
});
